INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1045','task-28','<p>「會員等級與點數系統」為前端功能，需確保 UI/UX 品質與跨裝置相容性。</p>','<p>1. 根據設計稿實作 UI 元件</p><p>2. 串接後端 API 並處理狀態管理</p><p>3. 響應式適配與瀏覽器相容性測試</p>','<p>前端功能需注意效能優化（首屏載入、懶加載）與無障礙支援。</p>');
