INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1187','task-170','<p>「會員等級與點數系統」是「CRM會員經營」的基礎設施/DevOps 任務，目標是提升系統可靠性、可觀測性或自動化程度，確保服務 SLA 達到 99.9% 可用性。</p>','<p>1. 評估「會員等級與點數系統」的技術方案，比較主要選項的優缺點</p><p>2. 撰寫技術設計文件（TDD），確認涉及服務與影響範圍</p><p>3. 在非生產環境（Dev/QA）驗證方案可行性</p><p>4. 制定上線計畫：部署步驟、回滾策略、監控指標</p><p>5. 執行上線，密切監控 30 分鐘確認無異常</p><p>6. 更新 Runbook 與架構圖，確保團隊知識共享</p><p>7. 上線一週後進行穩定性回顧，確認指標達標</p>','<p>生產環境變更需提前 24 小時通知 SRE Lead 謝宗霖，並在 #deployments 頻道發佈變更公告。所有基礎設施變更需記錄 Change Log 供事後追溯。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1188','task-171','<p>「報表Dashboard開發」是「CRM會員經營」的 UI/UX 設計任務，需輸出符合品牌規範、具備良好可用性的設計稿，作為前端工程師的實作依據。</p>','<p>1. 研究使用者需求與競品設計，確立「報表Dashboard開發」的設計方向</p><p>2. 產出 Wireframe，與 PM 確認流程與資訊架構</p><p>3. 製作高保真 Mockup，包含各狀態（載入中/空狀態/錯誤狀態）</p><p>4. 確保符合設計系統規範，優先重用現有元件</p><p>5. 完成響應式稿（桌面 1280px + 手機 375px）</p><p>6. 標注 Figma 設計稿所有間距、字型、顏色 Token</p><p>7. 進行設計評審，收集工程師可行性反饋後調整</p>','<p>設計完成後在 Figma 加版本標記（v1.0），連結更新至本任務。工程師如有疑問請在 Figma 元件上留 Comment，而非 Slack 私訊。動畫稿請輸出 Lottie JSON 格式。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1189','task-172','<p>德州撲克需要完整的房間管理系統。玩家應能創建房間、搜尋/加入現有房間，並在結局後乾淨地離開。此功能是整個遊戲大廳的核心入口，直接影響玩家的首次使用體驗。</p>','<p>1. 實作房間創建表單：房間名稱、人數上限（2–9 人）、買入金額、公開/密碼房設定</p><p>2. 實作房間列表頁：依狀態篩選（等待中/遊戲中）、支持房名關鍵字搜尋、顯示在線人數</p><p>3. 實作加入房間流程：邀請碼驗證、人數上限檢查、買入確認彈窗</p><p>4. 實作房間內玩家列表視圖：座位編號、頭像、暱稱、當前籌碼數</p><p>5. 實作離開房間與房主解散房間邏輯，離開時結算並返還剩餘籌碼</p><p>6. 透過 WebSocket 即時同步房間狀態，確保所有玩家看到相同視圖</p>','<p>此任務依賴後端房間 API（棋牌遊戲 — 後端API設計與實作），建議等 API Schema 確認後再動工前端。手機橫屏是必要體驗，請在 iPhone/Android 實機驗證。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1190','task-173','<p>後端房間 API 是整個德州撲克遊戲邏輯的基礎。需設計 RESTful + WebSocket 雙軌 API，涵蓋房間生命週期管理、玩家操作，以及遊戲狀態廣播，並在高並發下保持資料一致性。</p>','<p>1. 設計房間 CRUD API（POST/GET/DELETE /rooms），包含房間狀態機（等待中/遊戲中/已結束）</p><p>2. 設計玩家操作 API：加入（/join）、離開（/leave）、就座（/seat）</p><p>3. 設計遊戲邏輯 API：發牌、下注/加注/棄牌/過牌、攤牌結算</p><p>4. 設計 WebSocket 廣播頻道，推送房間內所有即時事件給玩家</p><p>5. 實作 API 認證中間件（JWT），確保所有操作均已授權</p><p>6. 撰寫 OpenAPI/Swagger 文件，並附上各端點的測試用例</p>','<p>房間內多玩家同時操作籌碼時需使用資料庫 Transaction 保證一致性。房間列表快取於 Redis（TTL 5s），降低資料庫壓力。API 設計完成後需舉行前後端 Schema 對齊會議。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1191','task-174','<p>棋牌遊戲涉及真實金額的虛擬籌碼交易，現有認證系統需升級以支援多產品線 Token scope 控制，同時強化安全防護，防止帳號盜用與異常登入。</p>','<p>1. 重構 JWT 生成邏輯：加入 product_scope（CARD/IDLE/RPG）欄位，不同產品線的 Token 互相隔離</p><p>2. 實作 Refresh Token 輪換（Rotation）機制，防止 Token 被竊取後長期濫用</p><p>3. 支援細粒度角色管理：普通玩家 / VIP / GM / 管理員，各角色有不同 API 存取權限</p><p>4. 記錄認證稽核日誌（登入 IP、裝置指紋、地理位置、成功/失敗）</p><p>5. 實作異常登入偵測（短時間多地登入），自動觸發二次驗證</p><p>6. 撰寫安全測試案例：暴力破解防護、XSS、CSRF、JWT 竄改</p>','<p>認證系統改動影響範圍極廣，Token 格式若有 Breaking Change 需提前一個 Sprint 通知前端，並提供新舊版本並行期（Deprecation Period）。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1192','task-175','<p>玩家需透過信用卡、超商或電子錢包購買遊戲籌碼。本任務整合 ECPay 與 LINE Pay，實作完整的支付流程，確保交易安全性與冪等性，避免重複扣款或遺失訂單。</p>','<p>1. 串接 ECPay 信用卡一次付清 API（含沙盒環境設定）</p><p>2. 串接 LINE Pay Request API，實作 Confirm 與 Refund 流程</p><p>3. 設計支付狀態機（PENDING → PROCESSING → SUCCESS / FAILED / REFUNDED）</p><p>4. 實作 Webhook 回調端點，處理支付服務商的非同步通知（冪等性保障）</p><p>5. 所有交易金額使用整數（新台幣元），禁止浮點運算</p><p>6. 撰寫沙盒整合測試：正常付款/逾時/餘額不足/退款等情境</p><p>7. 上線前完成資安掃描（OWASP ZAP）與 PCI DSS 自評</p>','<p>ECPay 沙盒測試卡號請從內部 Wiki 取得，不得提交至 Git。交易記錄需保留 7 年（法規要求）。正式特店帳號申請需提前 2 週，請盡早啟動。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1193','task-176','<p>遊戲即時性是多人棋牌的生命線。現有 HTTP 短輪詢方案延遲過高（>500ms），需改用 WebSocket，確保玩家操作（出牌/加注）能在 100ms 內廣播給房間內所有人。</p>','<p>1. 設計 WebSocket 連線管理架構：支援玩家上線、下線、重連，並與 Redis Session 整合</p><p>2. 實作房間頻道（Channel）訂閱：玩家加入房間即自動訂閱，離開後自動取消</p><p>3. 廣播遊戲事件：出牌、加注、棄牌、發牌、結算，延遲目標 < 100ms</p><p>4. 使用 Redis Pub/Sub 確保多節點部署下的消息一致性</p><p>5. 實作斷線重連機制：重連後補發玩家離線期間錯過的事件</p><p>6. 實作 Heartbeat 檢測（每 30 秒 ping），超時未回應則清理殭屍連線</p><p>7. 壓力測試：1000 個並發 WebSocket 連線，確認記憶體和 CPU 使用量在預期內</p>','<p>WebSocket 伺服器建議獨立部署（與 HTTP API 分開），方便水平擴展。前端需實作指數退避重連邏輯（1s → 2s → 4s → 8s），避免重連風暴。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1194','task-177','<p>遊戲的視覺品質直接影響玩家留存率。現有 UI 組件庫缺乏撲克專用元件，需設計可複用的卡牌、籌碼、牌桌佈局等組件，搭配流暢動畫提升沉浸感。</p>','<p>1. 設計 52 張撲克牌組件：正面花色數字、背面圖案、翻牌動畫（CSS 3D Transform）</p><p>2. 設計籌碼堆疊組件：支援 10/50/100/500/1000 面額，堆疊高度反映數量</p><p>3. 設計牌桌佈局：支援 2–9 人座位的扇形/橢圓佈局，自適應螢幕尺寸</p><p>4. 設計玩家資訊卡片：頭像、暱稱、籌碼數、倒計時圓環</p><p>5. 設計操作按鈕組（跟注/加注/棄牌），包含禁用/激活/Loading 狀態</p><p>6. 確保所有動畫在低端 Android（2018 年以後機型）上達到 30fps</p><p>7. 提供 Storybook 展示所有組件的各種狀態（空/有資料/Loading/錯誤）</p>','<p>設計稿由張靜如負責，取稿前請確認 Figma 版本標記為 v1.0+。動畫優先使用 CSS Animation，避免用 JS 操作 DOM 拖慢渲染。牌背圖案版權請法務確認。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1195','task-178','<p>遊戲公平性是棋牌產品的生命線，依靠人工測試覆蓋率低且容易遺漏邊界案例。需建立自動化測試框架，涵蓋發牌算法、牌型判斷、籌碼計算等核心邏輯。</p>','<p>1. 建立後端遊戲邏輯單元測試框架（Jest/JUnit），初期覆蓋率目標 ≥ 80%</p><p>2. 撰寫發牌算法測試：洗牌均勻性（Chi-Square 檢定）、防止重複牌</p><p>3. 撰寫牌型判斷測試：涵蓋全部 9 種牌型及特殊邊界（最小順子 A-2-3-4-5、同花全輸）</p><p>4. 撰寫籌碼計算測試：All-in 邊池（Side Pot）計算、多人平局等額分配</p><p>5. 撰寫 API 整合測試：模擬完整一局德州撲克（2–9 人）的 API 呼叫序列</p><p>6. 設立 CI Pipeline（GitHub Actions），每次 PR 自動執行測試</p><p>7. 設立每週覆蓋率趨勢報告，持續追蹤</p>','<p>隨機性相關測試（洗牌分布）需固定隨機種子（Seeded Random）確保可重現，或使用統計方法驗證（至少運行 10000 次取樣）。CI 執行時間目標 < 5 分鐘。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1196','task-179','<p>遊戲回放功能一方面讓玩家覆盤學習，另一方面作為爭議仲裁的客觀依據。需採用 Event Sourcing 模式記錄每局事件流，並提供前端回放播放器。</p>','<p>1. 設計遊戲事件記錄資料結構（room_id、event_type、payload、created_at），用 Event Sourcing 模式</p><p>2. 在遊戲邏輯服務加入事件記錄 Middleware，不影響主流程延遲（< 5ms overhead）</p><p>3. 設計冷熱分層存儲：30 天內完整記錄（PostgreSQL），之後壓縮歸檔至 S3</p><p>4. 實作回放查詢 API：依局號或玩家 ID 查詢事件流</p><p>5. 實作前端回放播放器：播放/暫停、2x/4x 快進、進度條拖拽</p><p>6. 玩家個人中心新增「我的回放」頁，支持搜尋與分頁</p>','<p>回放資料量估算：每局約 200 事件 × 每天 10000 局 = 200 萬事件/天。存儲策略請與 SRE 謝宗霖確認。回放播放器可先用 Mock 事件流開發 UI，不必等後端完成。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1197','task-180','<p>隨著日活增長，房間列表 API P99 延遲已達 2s，遠超目標 500ms。需系統性排查瓶頸，透過快取優化、索引調整及前端懶加載，將整體響應時間降至目標範圍。</p>','<p>1. 使用 APM 工具（New Relic/Datadog）定位 Top 10 慢查詢（> 100ms SQL）</p><p>2. 設計 Redis 快取策略：房間列表（TTL 5s）、玩家資料（TTL 60s）</p><p>3. 優化資料庫索引：為 WHERE/ORDER BY 高頻欄位補充缺失索引</p><p>4. 重構 N+1 Query 問題：改用批量查詢或 JOIN 替代多次查詢</p><p>5. 前端懶加載：React.lazy + Suspense 做路由級別的 Code Splitting</p><p>6. 靜態資源遷移至 CDN，確認快取 Header 設定（max-age、ETag）正確</p><p>7. 建立性能 Baseline，每次部署後自動對比 LCP/TTFB 指標</p>','<p>本任務聚焦 Quick Win（ROI 最高的優化），深層架構改造（分庫分表）另立任務。優化前後需有量化數據對比，以便向 PM 說明效益。目標：P99 < 300ms，FCP < 1.5s。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1198','task-181','<p>現有監控不完整，生產事故往往需要超過 30 分鐘才能定位根因。需建立涵蓋 Logs/Metrics/Traces 的完整可觀測性體系，達到 5 分鐘內告警、15 分鐘內定位的目標。</p>','<p>1. 部署 ELK Stack 集中管理應用日誌，設計結構化 JSON Log 格式</p><p>2. 規範關鍵字段（user_id, room_id, action, latency_ms）確保可查詢</p><p>3. 配置 Prometheus + Grafana：監控在線人數、TPS、Error Rate、P99 延遲</p><p>4. 設定告警規則：Error Rate > 1% → PagerDuty，延遲 > 1s → Slack</p><p>5. 整合 Jaeger 分散式追蹤，分析跨服務調用鏈（API → Cache → DB）</p><p>6. 建立 On-call Runbook，記錄常見告警的排查步驟與聯絡窗口</p><p>7. 日誌保留策略：Hot 7 天、Warm 30 天、Cold 90 天（S3）</p>','<p>告警閾值需與業務側校準，避免 Alert Fatigue（告警風暴）。Grafana Dashboard 提供兩層視圖：工程師技術視圖（詳細指標）和 PM 業務視圖（在線人數/收益趨勢）。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1199','task-182','<p>角色養成是休閒遊戲的核心留存機制，玩家透過升級、解鎖外觀持續回流。本任務負責設計角色養成系統的完整 UX 流程與視覺稿，為前端開發提供精準依據。</p>','<p>1. 設計角色養成主頁：角色 3D/2D 展示區、屬性列表、成長進度條</p><p>2. 設計技能/能力解鎖介面：樹狀結構，已解鎖/可解鎖/未達標各有明確視覺區分</p><p>3. 設計升級動畫稿（Lottie 格式）：升級光效、屬性浮字動畫</p><p>4. 設計各等級段角色外觀差異，讓玩家明顯感受到成長</p><p>5. 設計道具背包 UI：分類 Tab、道具詳情 Tooltip、使用確認彈窗</p><p>6. 產出完整 Figma 設計稿，標注所有 Token（顏色/字型/間距）</p><p>7. 製作 Figma 可互動原型，讓 PM 驗收養成流程的流暢度</p>','<p>角色外觀設計需考慮多種膚色和性別的包容性。動畫稿須輸出 Lottie JSON 格式，檔案大小控制在 300KB 以內。設計稿完成後送 PM 林佳蓉確認「成長感」是否達標。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1200','task-183','<p>依據設計稿實作角色養成系統前端，包含角色展示、技能樹互動、升級動畫等，需確保在手機端（375px）的流暢體驗，並正確串接後端養成 API。</p>','<p>1. 實作角色展示主頁，串接 /api/character/status 取得等級/屬性/外觀資料</p><p>2. 實作技能樹組件（SVG 節點 + 連線），支援依賴鎖定/解鎖狀態切換</p><p>3. 整合 Lottie-web 播放升級動畫，完成後清理 Lottie 實例避免記憶體洩漏</p><p>4. 實作屬性數值增長動畫（countUp.js 或自製 Hook）</p><p>5. 實作道具背包分頁列表，串接 /api/inventory API</p><p>6. 手機端適配：375px 寬度下技能樹可水平滑動，按鈕觸控面積 ≥ 44px</p><p>7. 懶加載技能樹節點圖示，避免首次渲染阻塞</p>','<p>此任務前置依賴設計稿（IDLE 設計任務）和後端 API（IDLE 後端 API 任務），請確認兩者均已就緒再開始動工，否則可先用 Mock 資料開發 UI。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1201','task-184','<p>等級成長是遊戲留存的核心驅動力。需設計靈活的 XP 規則引擎，支援多來源 XP 加成（任務/活動/道具），以及可動態調整的升級速度曲線。</p>','<p>1. 設計資料表：levels（等級設定）、xp_transactions（每筆 XP 記錄含來源）</p><p>2. 實作 XP 規則引擎：基礎 XP + 倍率加成（VIP 加成/活動加成/道具加成）</p><p>3. 實作升級判定邏輯：XP 累積達上限後觸發升級事件並發送 Notification</p><p>4. 設計等級上限為可配置參數（後台熱更新，不需重新部署）</p><p>5. 記錄每筆 XP 來源（for 數據分析及客訴查核）</p><p>6. 提供 GM 後台 API：查詢/修改特定玩家的等級與 XP</p><p>7. 壓測：同時 1000 名玩家獲取 XP，確認無 Race Condition</p>','<p>升級速度曲線需與 PM 林佳蓉確認遊戲節奏，一般建議前 20 級速升、後期放緩。玩家等級在 Redis 快取（TTL 無限，寫入時更新），降低高頻讀取的 DB 壓力。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1202','task-185','<p>「每日任務與獎勵系統」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1203','task-186','<p>「數據分析與玩家行為追蹤」涉及搜尋/數據/AI相關功能，需確保效能與準確性。</p>','<p>1. 確認搜尋索引與查詢優化策略</p><p>2. 實作並驗證搜尋結果品質</p><p>3. 效能壓測確保回應時間 < 200ms</p>','<p>搜尋相關功能需特別注意中文斷詞處理與索引更新策略。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1204','task-187','<p>「手機適配與響應式設計」是「休閒養成」的 UI/UX 設計任務，需輸出符合品牌規範、具備良好可用性的設計稿，作為前端工程師的實作依據。</p>','<p>1. 研究使用者需求與競品設計，確立「手機適配與響應式設計」的設計方向</p><p>2. 產出 Wireframe，與 PM 確認流程與資訊架構</p><p>3. 製作高保真 Mockup，包含各狀態（載入中/空狀態/錯誤狀態）</p><p>4. 確保符合設計系統規範，優先重用現有元件</p><p>5. 完成響應式稿（桌面 1280px + 手機 375px）</p><p>6. 標注 Figma 設計稿所有間距、字型、顏色 Token</p><p>7. 進行設計評審，收集工程師可行性反饋後調整</p>','<p>設計完成後在 Figma 加版本標記（v1.0），連結更新至本任務。工程師如有疑問請在 Figma 元件上留 Comment，而非 Slack 私訊。動畫稿請輸出 Lottie JSON 格式。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1205','task-188','<p>「測試計畫與用戶驗收準備」測試任務旨在確保「休閒養成」的功能品質，需設計涵蓋正常流程、邊界條件與例外情況的測試案例，在 QA 環境完成驗收後出具測試報告。</p>','<p>1. 閱讀「測試計畫與用戶驗收準備」的規格書，整理測試範圍（高風險功能優先）</p><p>2. 撰寫測試計畫：環境/策略/工具/測試資料準備</p><p>3. 設計測試案例：Happy Path + Edge Cases + Negative Tests</p><p>4. 執行功能測試，在任務留言更新測試結果（Pass/Fail/Blocked）</p><p>5. 執行回歸測試，確認不影響既有功能穩定性</p><p>6. Bug 回報：附上重現步驟、環境資訊、截圖/錄影</p><p>7. 輸出測試報告，列出已知問題與 Release 建議（Go/No-Go）</p>','<p>P1/P2 嚴重 Bug 請立刻在 Slack #urgent-bugs 頻道通知，不要等測試報告才揭露。測試環境為 QA 環境，不要在 Staging/Prod 進行破壞性測試。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1206','task-189','<p>「存檔與雲端同步機制」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1207','task-190','<p>「音樂與音效整合」為前端功能，需確保 UI/UX 品質與跨裝置相容性。</p>','<p>1. 根據設計稿實作 UI 元件</p><p>2. 串接後端 API 並處理狀態管理</p><p>3. 響應式適配與瀏覽器相容性測試</p>','<p>前端功能需注意效能優化（首屏載入、懶加載）與無障礙支援。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1208','task-191','<p>「伺服器負載測試與優化」測試任務旨在確保「休閒養成」的功能品質，需設計涵蓋正常流程、邊界條件與例外情況的測試案例，在 QA 環境完成驗收後出具測試報告。</p>','<p>1. 閱讀「伺服器負載測試與優化」的規格書，整理測試範圍（高風險功能優先）</p><p>2. 撰寫測試計畫：環境/策略/工具/測試資料準備</p><p>3. 設計測試案例：Happy Path + Edge Cases + Negative Tests</p><p>4. 執行功能測試，在任務留言更新測試結果（Pass/Fail/Blocked）</p><p>5. 執行回歸測試，確認不影響既有功能穩定性</p><p>6. Bug 回報：附上重現步驟、環境資訊、截圖/錄影</p><p>7. 輸出測試報告，列出已知問題與 Release 建議（Go/No-Go）</p>','<p>P1/P2 嚴重 Bug 請立刻在 Slack #urgent-bugs 頻道通知，不要等測試報告才揭露。測試環境為 QA 環境，不要在 Staging/Prod 進行破壞性測試。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1209','task-192','<p>「故事劇情與場景設計文件」是「RPG冒險世界」的產品規劃工作，目標是釐清業務需求、定義功能邊界，並與工程師、設計師對齊方向，輸出作為開發依據的規格文件。</p>','<p>1. 整理「故事劇情與場景設計文件」的業務背景與使用者情境（User Story）</p><p>2. 撰寫完整功能規格書：流程圖、邊界條件、例外處理規則</p><p>3. 與工程師確認技術可行性，完成工作量估算（Story Point）</p><p>4. 與設計師對齊互動流程，確認設計稿交付時程</p><p>5. 定義驗收標準（Acceptance Criteria），作為 QA 測試依據</p><p>6. 主持需求評審，收集各方意見並更新文件版本</p><p>7. 規格確認後同步更新至 Notion，並在任務留言貼上連結</p>','<p>規格文件如有需求變更，需走正式 Change Request 流程並通知相關人員。評審後的最終版本需加版本號（v1.0）以防混淆。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1210','task-193','<p>「角色系統與技能樹設計」是「RPG冒險世界」的 UI/UX 設計任務，需輸出符合品牌規範、具備良好可用性的設計稿，作為前端工程師的實作依據。</p>','<p>1. 研究使用者需求與競品設計，確立「角色系統與技能樹設計」的設計方向</p><p>2. 產出 Wireframe，與 PM 確認流程與資訊架構</p><p>3. 製作高保真 Mockup，包含各狀態（載入中/空狀態/錯誤狀態）</p><p>4. 確保符合設計系統規範，優先重用現有元件</p><p>5. 完成響應式稿（桌面 1280px + 手機 375px）</p><p>6. 標注 Figma 設計稿所有間距、字型、顏色 Token</p><p>7. 進行設計評審，收集工程師可行性反饋後調整</p>','<p>設計完成後在 Figma 加版本標記（v1.0），連結更新至本任務。工程師如有疑問請在 Figma 元件上留 Comment，而非 Slack 私訊。動畫稿請輸出 Lottie JSON 格式。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1211','task-194','<p>戰鬥 UI 的流暢度與視覺效果是 RPG 玩家留存的關鍵因素。需實作即時戰鬥介面，包含技能釋放動畫、傷害浮字、血量條動畫，並在手機端保持穩定幀率。</p>','<p>1. 實作戰鬥場景主佈局：我方角色區（下方）/ 敵方區（上方）/ 技能欄（底部）</p><p>2. 實作技能釋放流程：點擊 → 選定目標 → 播放 Lottie 動畫 → 計算結果顯示</p><p>3. 實作傷害浮字（Damage Number）：物理傷害白字、魔法傷害藍字、暴擊橙字並放大</p><p>4. 實作血量/魔力條漸變動畫：視覺化扣血過程，危血時顯示紅色閃爍警告</p><p>5. 實作 Boss 血條（頂部大型條）及技能預警 UI（紅色提示圈/警告文字）</p><p>6. 實作戰鬥結算畫面：勝利/失敗動畫、獎勵展示、戰鬥統計數據</p><p>7. 手機適配：技能按鈕位於拇指可觸及區域，支援橫屏模式</p>','<p>戰鬥 UI 依賴後端戰鬥引擎 API（RPG-4）的資料格式，建議先用 Mock 數據完成 UI，後端穩定後再整合。動畫資源（Lottie/Sprite）需由設計師提前確認格式與尺寸規格。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1212','task-195','<p>RPG 戰鬥引擎是整個遊戲的技術核心，需實作傷害計算公式、技能效果系統、BUFF/DEBUFF 狀態機及 Boss AI 行為樹，並保證多人副本下的狀態同步一致性。</p>','<p>1. 設計戰鬥狀態機：IDLE → COMBAT（回合制/即時制）→ SETTLEMENT</p><p>2. 實作傷害計算公式引擎：物攻/魔攻 × 技能倍率 × 暴擊係數 × 屬性剋制 × 防禦減傷</p><p>3. 實作技能效果系統：即時型/持續型/觸發型效果，支援效果堆疊規則</p><p>4. 實作 BUFF/DEBUFF 狀態機：持續回合數、疊加層數上限、免疫/抗性機制</p><p>5. 實作基礎 Boss AI 行為樹：血量階段觸發、技能冷卻、狂暴模式</p><p>6. 多人副本狀態同步：使用 Redis 鎖定回合，防止並發操作導致的不一致</p><p>7. 撰寫數值計算單元測試：每個公式輸入/輸出均有測試案例</p>','<p>戰鬥數值設計由策劃（PM 林佳蓉）負責，工程師在實作前必須取得最終規格文件版本，不要按草稿實作。Boss AI 的行為參數需支援後台配置，讓策劃不改代碼就能調整難度。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1213','task-196','<p>「地圖與怪物AI系統」涉及搜尋/數據/AI相關功能，需確保效能與準確性。</p>','<p>1. 確認搜尋索引與查詢優化策略</p><p>2. 實作並驗證搜尋結果品質</p><p>3. 效能壓測確保回應時間 < 200ms</p>','<p>搜尋相關功能需特別注意中文斷詞處理與索引更新策略。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1214','task-197','<p>「裝備與道具系統」為遊戲核心功能，需確保玩法平衡與用戶體驗。</p>','<p>1. 確認遊戲機制與數值設計</p><p>2. 實作核心遊戲邏輯</p><p>3. 平衡性測試與調整</p>','<p>遊戲功能需注意數值平衡與防作弊機制。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1215','task-198','<p>「多人副本與隊伍系統設計」是「RPG冒險世界」的產品規劃工作，目標是釐清業務需求、定義功能邊界，並與工程師、設計師對齊方向，輸出作為開發依據的規格文件。</p>','<p>1. 整理「多人副本與隊伍系統設計」的業務背景與使用者情境（User Story）</p><p>2. 撰寫完整功能規格書：流程圖、邊界條件、例外處理規則</p><p>3. 與工程師確認技術可行性，完成工作量估算（Story Point）</p><p>4. 與設計師對齊互動流程，確認設計稿交付時程</p><p>5. 定義驗收標準（Acceptance Criteria），作為 QA 測試依據</p><p>6. 主持需求評審，收集各方意見並更新文件版本</p><p>7. 規格確認後同步更新至 Notion，並在任務留言貼上連結</p>','<p>規格文件如有需求變更，需走正式 Change Request 流程並通知相關人員。評審後的最終版本需加版本號（v1.0）以防混淆。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1216','task-199','<p>「移動平台適配」為前端功能，需確保 UI/UX 品質與跨裝置相容性。</p>','<p>1. 根據設計稿實作 UI 元件</p><p>2. 串接後端 API 並處理狀態管理</p><p>3. 響應式適配與瀏覽器相容性測試</p>','<p>前端功能需注意效能優化（首屏載入、懶加載）與無障礙支援。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1217','task-200','<p>「QA測試與錯誤修復」測試任務旨在確保「RPG冒險世界」的功能品質，需設計涵蓋正常流程、邊界條件與例外情況的測試案例，在 QA 環境完成驗收後出具測試報告。</p>','<p>1. 閱讀「QA測試與錯誤修復」的規格書，整理測試範圍（高風險功能優先）</p><p>2. 撰寫測試計畫：環境/策略/工具/測試資料準備</p><p>3. 設計測試案例：Happy Path + Edge Cases + Negative Tests</p><p>4. 執行功能測試，在任務留言更新測試結果（Pass/Fail/Blocked）</p><p>5. 執行回歸測試，確認不影響既有功能穩定性</p><p>6. Bug 回報：附上重現步驟、環境資訊、截圖/錄影</p><p>7. 輸出測試報告，列出已知問題與 Release 建議（Go/No-Go）</p>','<p>P1/P2 嚴重 Bug 請立刻在 Slack #urgent-bugs 頻道通知，不要等測試報告才揭露。測試環境為 QA 環境，不要在 Staging/Prod 進行破壞性測試。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1218','task-201','<p>「伺服器架構與CDN部署」是「RPG冒險世界」的基礎設施/DevOps 任務，目標是提升系統可靠性、可觀測性或自動化程度，確保服務 SLA 達到 99.9% 可用性。</p>','<p>1. 評估「伺服器架構與CDN部署」的技術方案，比較主要選項的優缺點</p><p>2. 撰寫技術設計文件（TDD），確認涉及服務與影響範圍</p><p>3. 在非生產環境（Dev/QA）驗證方案可行性</p><p>4. 制定上線計畫：部署步驟、回滾策略、監控指標</p><p>5. 執行上線，密切監控 30 分鐘確認無異常</p><p>6. 更新 Runbook 與架構圖，確保團隊知識共享</p><p>7. 上線一週後進行穩定性回顧，確認指標達標</p>','<p>生產環境變更需提前 24 小時通知 SRE Lead 謝宗霖，並在 #deployments 頻道發佈變更公告。所有基礎設施變更需記錄 Change Log 供事後追溯。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1219','task-202','<p>商城首頁是流量最高的頁面，現有設計老舊且移動端體驗差。本任務完整改版首頁視覺設計，提升第一屏轉化率，輸出供前端開發取用的 Figma 設計稿。</p>','<p>1. 進行競品分析（PChome/momo/蝦皮），整理當前趨勢並提出設計方向建議</p><p>2. 設計首頁模組化佈局：Hero Banner、個人化推薦商品、活動入口、品牌館</p><p>3. 分別設計桌面版（1280px）和手機版（375px）兩套稿</p><p>4. 設計 Banner 輪播組件，支援圖片/短影片混排，含切換動畫</p><p>5. 設計空狀態、Loading Skeleton，確保頁面首載體驗流暢</p><p>6. 製作 Figma Prototype，展示 Banner 輪播、滑動等互動效果</p><p>7. 根據 PM 和工程師評審意見調整後，加版本標記（v1.0）輸出</p>','<p>設計須沿用現有 Design Token，不能引入新顏色或字型。Banner 圖片規格（尺寸/格式/最大 KB）需明確標注，方便後續內容運營製作素材。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1220','task-203','<p>現有首頁使用舊版 jQuery + Bootstrap，效能差且維護困難。本任務將首頁遷移至 React + TailwindCSS 技術棧，同時完成響應式適配，確保 Core Web Vitals 達到 Google 綠燈標準。</p>','<p>1. 將首頁 jQuery 邏輯遷移至 React 組件（Banner/商品卡/活動區塊）</p><p>2. 實作 Banner 輪播：無縫切換、自動播放（5s）、手機觸滑切換、鍵盤導航</p><p>3. 串接推薦引擎 API，實作個人化商品列表（含 Loading Skeleton）</p><p>4. 完成 RWD 適配：桌面（≥1024px）/ 平板（768–1023px）/ 手機（< 768px）</p><p>5. LCP 優化：首屏 Banner 圖採 <link rel="preload">，非首屏圖片使用懶加載</p><p>6. 在 Safari / Chrome / Firefox 及 iOS / Android 主流機型驗證</p><p>7. 新舊版本功能回歸測試：確認原有功能（搜尋/購物車入口）不受影響</p>','<p>LCP 目標 < 2.5s（Core Web Vitals）。舊 jQuery 代碼暫不刪除（保留 `index.legacy.html`），確認新版穩定後下一 Sprint 再清理。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1221','task-204','<p>「商品列表與篩選優化」為前端功能，需確保 UI/UX 品質與跨裝置相容性。</p>','<p>1. 根據設計稿實作 UI 元件</p><p>2. 串接後端 API 並處理狀態管理</p><p>3. 響應式適配與瀏覽器相容性測試</p>','<p>前端功能需注意效能優化（首屏載入、懶加載）與無障礙支援。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1222','task-205','<p>購物車與結帳是電商的核心轉化路徑，現有並發扣庫存存在超賣風險，結帳 API P99 延遲達 1.8s。本任務重構後端，解決超賣問題並降低結帳延遲至 < 500ms。</p>','<p>1. 重設計購物車資料模型：登入用戶雲端同步，未登入使用 LocalStorage</p><p>2. 實作庫存扣減的樂觀鎖機制（version 欄位），防止並發超賣</p><p>3. 實作購物車 API：新增/修改/刪除商品、計算商品小計</p><p>4. 實作結帳預覽 API：計算運費規則、優惠券折扣、稅金、最終金額</p><p>5. 實作訂單創建 API：訂單創建與庫存扣減在同一資料庫 Transaction</p><p>6. 實作訂單超時自動取消（30 分鐘）：Redis TTL 觸發、釋放庫存</p><p>7. 壓力測試：並發 100 人搶購同一限量商品，確認無超賣</p>','<p>庫存扣減使用 SELECT ... FOR UPDATE 或 UPDATE ... WHERE stock > 0 原子操作。高峰期（雙十一）預估 TPS 請與 SRE（謝宗霖）提前確認，做好容量規劃。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1223','task-206','<p>「商品推薦引擎」涉及搜尋/數據/AI相關功能，需確保效能與準確性。</p>','<p>1. 確認搜尋索引與查詢優化策略</p><p>2. 實作並驗證搜尋結果品質</p><p>3. 效能壓測確保回應時間 < 200ms</p>','<p>搜尋相關功能需特別注意中文斷詞處理與索引更新策略。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1224','task-207','<p>「庫存管理系統」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1225','task-208','<p>「用戶評論與評分系統」是「商城主站」的產品規劃工作，目標是釐清業務需求、定義功能邊界，並與工程師、設計師對齊方向，輸出作為開發依據的規格文件。</p>','<p>1. 整理「用戶評論與評分系統」的業務背景與使用者情境（User Story）</p><p>2. 撰寫完整功能規格書：流程圖、邊界條件、例外處理規則</p><p>3. 與工程師確認技術可行性，完成工作量估算（Story Point）</p><p>4. 與設計師對齊互動流程，確認設計稿交付時程</p><p>5. 定義驗收標準（Acceptance Criteria），作為 QA 測試依據</p><p>6. 主持需求評審，收集各方意見並更新文件版本</p><p>7. 規格確認後同步更新至 Notion，並在任務留言貼上連結</p>','<p>規格文件如有需求變更，需走正式 Change Request 流程並通知相關人員。評審後的最終版本需加版本號（v1.0）以防混淆。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1226','task-209','<p>「行銷活動與優惠卷系統」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1227','task-210','<p>「性能測試與優化（首屏加載）」測試任務旨在確保「商城主站」的功能品質，需設計涵蓋正常流程、邊界條件與例外情況的測試案例，在 QA 環境完成驗收後出具測試報告。</p>','<p>1. 閱讀「性能測試與優化（首屏加載）」的規格書，整理測試範圍（高風險功能優先）</p><p>2. 撰寫測試計畫：環境/策略/工具/測試資料準備</p><p>3. 設計測試案例：Happy Path + Edge Cases + Negative Tests</p><p>4. 執行功能測試，在任務留言更新測試結果（Pass/Fail/Blocked）</p><p>5. 執行回歸測試，確認不影響既有功能穩定性</p><p>6. Bug 回報：附上重現步驟、環境資訊、截圖/錄影</p><p>7. 輸出測試報告，列出已知問題與 Release 建議（Go/No-Go）</p>','<p>P1/P2 嚴重 Bug 請立刻在 Slack #urgent-bugs 頻道通知，不要等測試報告才揭露。測試環境為 QA 環境，不要在 Staging/Prod 進行破壞性測試。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1228','task-211','<p>「上線前最終檢查與部署」是「商城主站」的基礎設施/DevOps 任務，目標是提升系統可靠性、可觀測性或自動化程度，確保服務 SLA 達到 99.9% 可用性。</p>','<p>1. 評估「上線前最終檢查與部署」的技術方案，比較主要選項的優缺點</p><p>2. 撰寫技術設計文件（TDD），確認涉及服務與影響範圍</p><p>3. 在非生產環境（Dev/QA）驗證方案可行性</p><p>4. 制定上線計畫：部署步驟、回滾策略、監控指標</p><p>5. 執行上線，密切監控 30 分鐘確認無異常</p><p>6. 更新 Runbook 與架構圖，確保團隊知識共享</p><p>7. 上線一週後進行穩定性回顧，確認指標達標</p>','<p>生產環境變更需提前 24 小時通知 SRE Lead 謝宗霖，並在 #deployments 頻道發佈變更公告。所有基礎設施變更需記錄 Change Log 供事後追溯。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1229','task-212','<p>金流系統需支援台灣主流支付（信用卡/超商/ATM/LINE Pay/Apple Pay）。本任務設計支付方式的整體抽象架構與各方式的完整流程規格，作為後續串接開發的依據文件。</p>','<p>1. 研讀各支付服務商的 API 文件（ECPay/LINE Pay/Apple Pay），整理差異與限制</p><p>2. 設計 Payment Provider 抽象介面（Interface），確保可插拔、統一調用</p><p>3. 繪製各支付方式的完整流程圖：正常/失敗/退款/逾時各一份</p><p>4. 確認 PCI DSS 合規要求，標記哪些環節不可自行處理卡號資料</p><p>5. 與資安同仁確認敏感資料處理規範（Token 化/加密策略）</p><p>6. 評估各支付方式的接入成本（手續費率/年費/技術工時）</p><p>7. 輸出《支付系統技術架構文件 v1.0》供工程師評審</p>','<p>支付規格文件屬機密，不得放入公開 Git。API Key 請存入 1Password（team-vault/payment）。架構設計需由李承恩做技術評審，通過後才能開始開發任務。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1230','task-213','<p>本任務實作金流後端與 ECPay 的完整 API 整合，包含建立連線、發起交易、查詢狀態、處理非同步回調及對帳功能，是整個金流系統的技術核心。</p>','<p>1. 串接 ECPay 信用卡一次付清（含 3DS 驗證流程）及沙盒環境設定</p><p>2. 串接超商代碼繳費：7-11/全家/萊爾富代碼生成及繳費完成通知</p><p>3. 串接 ATM 虛擬帳號：帳號生成（各銀行）及繳費確認 Webhook</p><p>4. 實作支付結果 Webhook 接收端點，確保冪等性（同一 trade_no 多次通知只處理一次）</p><p>5. 實作交易主動查詢 API（用於逾時未收到通知時補查狀態）</p><p>6. 記錄完整交易日誌：每次 Request/Response（API Key 需遮罩）</p><p>7. 建立沙盒整合測試套件，覆蓋 12 種支付情境（付款成功/失敗/逾時/退款）</p>','<p>ECPay 沙盒測試帳號請從內部 Wiki 查詢，不得 commit 至 Git。正式特店帳號申請需提前 2 週，請 PM 黃心怡盡早啟動申請流程。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1231','task-214','<p>支付服務商以 Webhook 非同步通知支付結果，若處理不當容易造成訂單狀態卡住或重複觸發業務邏輯。本任務設計可靠的非同步通知處理架構，確保冪等性與可追溯性。</p>','<p>1. 設計 Webhook 接收端點（POST /webhooks/payment），驗證簽名防偽造</p><p>2. 實作冪等鍵（Idempotency Key）機制，同一通知多次投遞只執行一次業務邏輯</p><p>3. 設計 Webhook 事件佇列（Redis Queue/SQS），解耦接收與處理</p><p>4. 實作消費者（Worker）處理業務邏輯：更新訂單狀態、觸發發貨/發點數</p><p>5. 設計重試機制：處理失敗的事件自動重試（指數退避，最多 5 次）</p><p>6. 記錄每個 Webhook 事件的完整生命週期（接收/處理/完成/失敗）</p><p>7. 建立死信佇列（Dead Letter Queue），人工介入處理無法自動解決的事件</p>','<p>收到 Webhook 後，接收端點應立刻回傳 HTTP 200（避免服務商重試），再異步處理業務邏輯。所有 Webhook 請求的 IP 白名單需向各支付服務商索取。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1232','task-215','<p>退款流程涉及與多個支付服務商的 API 互動，以及庫存還原、積分扣回等跨系統操作，需要設計嚴謹的事務控制確保業務一致性。</p>','<p>1. 設計退款狀態機：REFUND_REQUESTED → PROCESSING → SUCCESS / FAILED</p><p>2. 實作各支付方式的退款 API 串接（信用卡沖銷/超商無法退款的通知邏輯）</p><p>3. 實作部分退款與全額退款的金額計算（含優惠券分攤邏輯）</p><p>4. 退款成功後觸發補償事務：恢復庫存、扣回已使用積分、撤銷發票</p><p>5. 實作退款逾期自動失敗機制（超過 7 天未完成則 reject）</p><p>6. 後台提供退款申請審核介面（超過金額門檻需人工審核）</p><p>7. 撰寫退款整合測試，覆蓋各支付方式的退款情境</p>','<p>退款業務邏輯複雜，建議用 Saga Pattern（補償事務）確保各子步驟可回滾。超商繳費通常不支援退款（需改以匯款方式），相關流程需 PM 黃心怡確認文案。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1233','task-216','<p>支付前端是購買流程的最後一步，UI 的清晰度和安全感直接影響轉化率。需實作 PCI DSS 合規的信用卡輸入介面，並整合 3DS 驗證流程，確保手機端體驗流暢。</p>','<p>1. 實作支付方式選擇頁：信用卡/超商/ATM/LINE Pay 各有清晰圖示說明</p><p>2. 使用 ECPay 提供的 JS SDK 嵌入信用卡輸入框，不直接處理原始卡號（PCI DSS 合規）</p><p>3. 實作卡號格式化顯示（XXXX-XXXX-XXXX-XXXX）與即時格式驗證</p><p>4. 實作 3DS 驗證彈窗（iframe 載入銀行驗證頁），完成後回傳驗證結果</p><p>5. 實作超商選擇介面（7-11/全家/萊爾富），附上各超商繳費流程說明</p><p>6. 實作支付 Loading 頁（顯示「請勿關閉頁面」）及結果頁（成功/失敗/待確認）</p><p>7. 手機端適配：數字鍵盤弈出時避免表單被遮擋，iOS Safari 的 iframe 行為需專項測試</p>','<p>前端 Console Log 嚴禁輸出任何信用卡資訊（卡號/CVV/持卡人姓名）。支付頁面強制 HTTPS，CSP 政策限制只能載入可信的 ECPay SDK 域名。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1234','task-217','<p>「交易記錄與對帳系統」是金流系統的後端功能，特別需注意支付冪等性、資料一致性與 PCI DSS 合規。任何支付相關 Bug 可能直接造成財務損失，必須謹慎設計。</p>','<p>1. 確認涉及的支付服務商 API 文件，建立沙盒測試環境</p><p>2. 設計交易資料表 Schema，考量對帳/報表查詢需求</p><p>3. 實作核心支付邏輯，確保冪等性（同一交易號重複請求不重複扣款）</p><p>4. 實作非同步回調（Webhook）處理，含重試機制</p><p>5. 加入完整的錯誤處理與交易狀態機</p><p>6. 撰寫整合測試，覆蓋正常/失敗/超時/退款等 12 種情境</p><p>7. Code Review 完成後更新 API 文件</p>','<p>交易金額統一用整數（新台幣元），禁止浮點運算。所有 API 請求記錄完整 Log（API Key 需遮罩）。正式上線前必須完成 OWASP ZAP 安全掃描。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1235','task-218','<p>「安全審計與合規檢查」是「金流系統」的基礎設施/DevOps 任務，目標是提升系統可靠性、可觀測性或自動化程度，確保服務 SLA 達到 99.9% 可用性。</p>','<p>1. 評估「安全審計與合規檢查」的技術方案，比較主要選項的優缺點</p><p>2. 撰寫技術設計文件（TDD），確認涉及服務與影響範圍</p><p>3. 在非生產環境（Dev/QA）驗證方案可行性</p><p>4. 制定上線計畫：部署步驟、回滾策略、監控指標</p><p>5. 執行上線，密切監控 30 分鐘確認無異常</p><p>6. 更新 Runbook 與架構圖，確保團隊知識共享</p><p>7. 上線一週後進行穩定性回顧，確認指標達標</p>','<p>生產環境變更需提前 24 小時通知 SRE Lead 謝宗霖，並在 #deployments 頻道發佈變更公告。所有基礎設施變更需記錄 Change Log 供事後追溯。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1236','task-219','<p>「加密與數據安全實作」涉及搜尋/數據/AI相關功能，需確保效能與準確性。</p>','<p>1. 確認搜尋索引與查詢優化策略</p><p>2. 實作並驗證搜尋結果品質</p><p>3. 效能壓測確保回應時間 < 200ms</p>','<p>搜尋相關功能需特別注意中文斷詞處理與索引更新策略。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1237','task-220','<p>「支付流程全面測試」測試任務旨在確保「金流系統」的功能品質，需設計涵蓋正常流程、邊界條件與例外情況的測試案例，在 QA 環境完成驗收後出具測試報告。</p>','<p>1. 閱讀「支付流程全面測試」的規格書，整理測試範圍（高風險功能優先）</p><p>2. 撰寫測試計畫：環境/策略/工具/測試資料準備</p><p>3. 設計測試案例：Happy Path + Edge Cases + Negative Tests</p><p>4. 執行功能測試，在任務留言更新測試結果（Pass/Fail/Blocked）</p><p>5. 執行回歸測試，確認不影響既有功能穩定性</p><p>6. Bug 回報：附上重現步驟、環境資訊、截圖/錄影</p><p>7. 輸出測試報告，列出已知問題與 Release 建議（Go/No-Go）</p>','<p>P1/P2 嚴重 Bug 請立刻在 Slack #urgent-bugs 頻道通知，不要等測試報告才揭露。測試環境為 QA 環境，不要在 Staging/Prod 進行破壞性測試。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1238','task-221','<p>「監控告警與故障恢復」是「金流系統」的基礎設施/DevOps 任務，目標是提升系統可靠性、可觀測性或自動化程度，確保服務 SLA 達到 99.9% 可用性。</p>','<p>1. 評估「監控告警與故障恢復」的技術方案，比較主要選項的優缺點</p><p>2. 撰寫技術設計文件（TDD），確認涉及服務與影響範圍</p><p>3. 在非生產環境（Dev/QA）驗證方案可行性</p><p>4. 制定上線計畫：部署步驟、回滾策略、監控指標</p><p>5. 執行上線，密切監控 30 分鐘確認無異常</p><p>6. 更新 Runbook 與架構圖，確保團隊知識共享</p><p>7. 上線一週後進行穩定性回顧，確認指標達標</p>','<p>生產環境變更需提前 24 小時通知 SRE Lead 謝宗霖，並在 #deployments 頻道發佈變更公告。所有基礎設施變更需記錄 Change Log 供事後追溯。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1239','task-222','<p>現有會員系統僅有基本分級（普通/VIP），缺乏精細化的用戶畫像。本任務設計基於 RFM 模型的分層策略，規劃標籤體系，作為後續精準行銷的基礎。</p>','<p>1. 分析現有會員消費資料，了解 R（最近消費）、F（購買頻率）、M（消費金額）的分布</p><p>2. 設計 RFM 分層模型：定義各維度的計算口徑（時間窗口/交易類型）與分箱閾值</p><p>3. 規劃會員標籤體系：人口屬性標籤（年齡層/地區）、行為標籤（偏好品類/購買時段）</p><p>4. 設計分層結果 Dashboard，讓業務同仁可自助查詢各分層人數及特徵</p><p>5. 輸出各分層的行銷策略建議（觸發時機/溝通管道/訊息模板/頻率上限）</p><p>6. 撰寫《會員分層規格書 v1.0》，包含計算公式、更新頻率與維護責任人</p><p>7. 與數據工程師方彥廷確認資料可用性、計算成本及資料品質問題</p>','<p>RFM 分箱閾值需根據真實業務數據設定，不要直接套用教科書範例值。分層模型每季更新一次，更新前需用 AB Test 驗證新模型的效果優於現有版本。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1240','task-223','<p>會員資料是 CRM 系統的核心資產。需建立可靠的會員資料統一管理後端，整合電商/遊戲/支付三個業務系統的會員身份，提供統一的查詢與更新介面。</p>','<p>1. 設計統一的 Unified Member Profile 資料模型，整合各系統的會員 ID 映射</p><p>2. 實作批量匯入 API（CSV/JSON 格式），支援增量更新和全量替換兩種模式</p><p>3. 實作會員搜尋 API：支援姓名/手機/Email 模糊搜尋，返回結果分頁</p><p>4. 設計資料版本控制（Audit Trail）：記錄每次欄位修改的前後值和操作人</p><p>5. 實作跨系統資料同步機制：其他系統的會員資料變更透過 Event Bus 同步至 CRM</p><p>6. 實作 PII 欄位加密（手機/Email/身分證），存取需記錄稽核日誌</p><p>7. 實作 GDPR 資料刪除 API：接受刪除申請，30 天內完成所有系統的資料清除</p>','<p>跨系統會員身份合併需設計去重策略（以手機號為主鍵，Email 為輔助），合併前需人工確認模糊匹配案例。GDPR 刪除申請應設置 SLA 追蹤，避免逾期違規。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1241','task-224','<p>「會員等級與積分系統」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1242','task-225','<p>個人中心是會員查詢帳戶資訊、管理訂閱偏好的主要入口，同時也是品牌與高價值用戶互動的重要場景。需提供清晰的個人資料管理、訂單查詢、積分明細等功能。</p>','<p>1. 實作個人資料編輯頁：修改姓名/電話/生日/密碼，頭像上傳（最大 2MB，自動壓縮）</p><p>2. 實作訂單歷史頁：依日期範圍篩選、狀態過濾（待付款/配送中/已完成/退款中）</p><p>3. 實作積分明細頁：每筆積分獲取/使用記錄，加上月度趨勢折線圖</p><p>4. 實作會員等級頁：當前等級及權益說明、距下一等級進度條、保級條件說明</p><p>5. 實作隱私設定頁：Email/SMS/App 推播的訂閱偏好細粒度管理</p><p>6. 實作「申請刪除帳號」流程（需輸入密碼二次確認，後台人工審核）</p><p>7. 確保 App 內嵌 WebView 正常顯示（與 App 團隊確認 UA 識別方式）</p>','<p>所有個人資料 API 請求必須攜帶有效 JWT Token，並記錄稽核日誌。刪除帳號流程需在 UI 上清楚說明影響範圍（訂單/積分/遊戲資料等），避免用戶誤操作後投訴。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1243','task-226','<p>「營銷活動與自動化推送」測試任務旨在確保「CRM會員經營」的功能品質，需設計涵蓋正常流程、邊界條件與例外情況的測試案例，在 QA 環境完成驗收後出具測試報告。</p>','<p>1. 閱讀「營銷活動與自動化推送」的規格書，整理測試範圍（高風險功能優先）</p><p>2. 撰寫測試計畫：環境/策略/工具/測試資料準備</p><p>3. 設計測試案例：Happy Path + Edge Cases + Negative Tests</p><p>4. 執行功能測試，在任務留言更新測試結果（Pass/Fail/Blocked）</p><p>5. 執行回歸測試，確認不影響既有功能穩定性</p><p>6. Bug 回報：附上重現步驟、環境資訊、截圖/錄影</p><p>7. 輸出測試報告，列出已知問題與 Release 建議（Go/No-Go）</p>','<p>P1/P2 嚴重 Bug 請立刻在 Slack #urgent-bugs 頻道通知，不要等測試報告才揭露。測試環境為 QA 環境，不要在 Staging/Prod 進行破壞性測試。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1244','task-227','<p>「會員數據分析與報表」涉及搜尋/數據/AI相關功能，需確保效能與準確性。</p>','<p>1. 確認搜尋索引與查詢優化策略</p><p>2. 實作並驗證搜尋結果品質</p><p>3. 效能壓測確保回應時間 < 200ms</p>','<p>搜尋相關功能需特別注意中文斷詞處理與索引更新策略。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1245','task-228','<p>「會員留存與流失預測」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1246','task-229','<p>「管理後台UI設計」是「CRM會員經營」的 UI/UX 設計任務，需輸出符合品牌規範、具備良好可用性的設計稿，作為前端工程師的實作依據。</p>','<p>1. 研究使用者需求與競品設計，確立「管理後台UI設計」的設計方向</p><p>2. 產出 Wireframe，與 PM 確認流程與資訊架構</p><p>3. 製作高保真 Mockup，包含各狀態（載入中/空狀態/錯誤狀態）</p><p>4. 確保符合設計系統規範，優先重用現有元件</p><p>5. 完成響應式稿（桌面 1280px + 手機 375px）</p><p>6. 標注 Figma 設計稿所有間距、字型、顏色 Token</p><p>7. 進行設計評審，收集工程師可行性反饋後調整</p>','<p>設計完成後在 Figma 加版本標記（v1.0），連結更新至本任務。工程師如有疑問請在 Figma 元件上留 Comment，而非 Slack 私訊。動畫稿請輸出 Lottie JSON 格式。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1247','task-230','<p>「系統測試與文件準備」是「CRM會員經營」的產品規劃工作，目標是釐清業務需求、定義功能邊界，並與工程師、設計師對齊方向，輸出作為開發依據的規格文件。</p>','<p>1. 整理「系統測試與文件準備」的業務背景與使用者情境（User Story）</p><p>2. 撰寫完整功能規格書：流程圖、邊界條件、例外處理規則</p><p>3. 與工程師確認技術可行性，完成工作量估算（Story Point）</p><p>4. 與設計師對齊互動流程，確認設計稿交付時程</p><p>5. 定義驗收標準（Acceptance Criteria），作為 QA 測試依據</p><p>6. 主持需求評審，收集各方意見並更新文件版本</p><p>7. 規格確認後同步更新至 Notion，並在任務留言貼上連結</p>','<p>規格文件如有需求變更，需走正式 Change Request 流程並通知相關人員。評審後的最終版本需加版本號（v1.0）以防混淆。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1248','task-231','<p>「數據備份與系統監控」是「CRM會員經營」的基礎設施/DevOps 任務，目標是提升系統可靠性、可觀測性或自動化程度，確保服務 SLA 達到 99.9% 可用性。</p>','<p>1. 評估「數據備份與系統監控」的技術方案，比較主要選項的優缺點</p><p>2. 撰寫技術設計文件（TDD），確認涉及服務與影響範圍</p><p>3. 在非生產環境（Dev/QA）驗證方案可行性</p><p>4. 制定上線計畫：部署步驟、回滾策略、監控指標</p><p>5. 執行上線，密切監控 30 分鐘確認無異常</p><p>6. 更新 Runbook 與架構圖，確保團隊知識共享</p><p>7. 上線一週後進行穩定性回顧，確認指標達標</p>','<p>生產環境變更需提前 24 小時通知 SRE Lead 謝宗霖，並在 #deployments 頻道發佈變更公告。所有基礎設施變更需記錄 Change Log 供事後追溯。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1249','task-232','<p>「錦標賽賽制規格文件確認」是「棋牌遊戲」的產品規劃工作，目標是釐清業務需求、定義功能邊界，並與工程師、設計師對齊方向，輸出作為開發依據的規格文件。</p>','<p>1. 整理「錦標賽賽制規格文件確認」的業務背景與使用者情境（User Story）</p><p>2. 撰寫完整功能規格書：流程圖、邊界條件、例外處理規則</p><p>3. 與工程師確認技術可行性，完成工作量估算（Story Point）</p><p>4. 與設計師對齊互動流程，確認設計稿交付時程</p><p>5. 定義驗收標準（Acceptance Criteria），作為 QA 測試依據</p><p>6. 主持需求評審，收集各方意見並更新文件版本</p><p>7. 規格確認後同步更新至 Notion，並在任務留言貼上連結</p>','<p>規格文件如有需求變更，需走正式 Change Request 流程並通知相關人員。評審後的最終版本需加版本號（v1.0）以防混淆。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1250','task-233','<p>「錦標賽後端 API 開發」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1251','task-234','<p>「錦標賽報名頁面前端」為前端功能，需確保 UI/UX 品質與跨裝置相容性。</p>','<p>1. 根據設計稿實作 UI 元件</p><p>2. 串接後端 API 並處理狀態管理</p><p>3. 響應式適配與瀏覽器相容性測試</p>','<p>前端功能需注意效能優化（首屏載入、懶加載）與無障礙支援。</p>');
