INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1330','task-313','<p>「智能搜尋關鍵詞即時建議」涉及搜尋/數據/AI相關功能，需確保效能與準確性。</p>','<p>1. 確認搜尋索引與查詢優化策略</p><p>2. 實作並驗證搜尋結果品質</p><p>3. 效能壓測確保回應時間 < 200ms</p>','<p>搜尋相關功能需特別注意中文斷詞處理與索引更新策略。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1331','task-314','<p>「訂單退款申請流程後端」是金流系統的後端功能，特別需注意支付冪等性、資料一致性與 PCI DSS 合規。任何支付相關 Bug 可能直接造成財務損失，必須謹慎設計。</p>','<p>1. 確認涉及的支付服務商 API 文件，建立沙盒測試環境</p><p>2. 設計交易資料表 Schema，考量對帳/報表查詢需求</p><p>3. 實作核心支付邏輯，確保冪等性（同一交易號重複請求不重複扣款）</p><p>4. 實作非同步回調（Webhook）處理，含重試機制</p><p>5. 加入完整的錯誤處理與交易狀態機</p><p>6. 撰寫整合測試，覆蓋正常/失敗/超時/退款等 12 種情境</p><p>7. Code Review 完成後更新 API 文件</p>','<p>交易金額統一用整數（新台幣元），禁止浮點運算。所有 API 請求記錄完整 Log（API Key 需遮罩）。正式上線前必須完成 OWASP ZAP 安全掃描。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1332','task-315','<p>「賣家後台商品管理系統前端」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
