INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1382','task-365','<p>「RFM 分析儀表板視覺化開發」是「CRM會員經營」的 UI/UX 設計任務，需輸出符合品牌規範、具備良好可用性的設計稿，作為前端工程師的實作依據。</p>','<p>1. 研究使用者需求與競品設計，確立「RFM 分析儀表板視覺化開發」的設計方向</p><p>2. 產出 Wireframe，與 PM 確認流程與資訊架構</p><p>3. 製作高保真 Mockup，包含各狀態（載入中/空狀態/錯誤狀態）</p><p>4. 確保符合設計系統規範，優先重用現有元件</p><p>5. 完成響應式稿（桌面 1280px + 手機 375px）</p><p>6. 標注 Figma 設計稿所有間距、字型、顏色 Token</p><p>7. 進行設計評審，收集工程師可行性反饋後調整</p>','<p>設計完成後在 Figma 加版本標記（v1.0），連結更新至本任務。工程師如有疑問請在 Figma 元件上留 Comment，而非 Slack 私訊。動畫稿請輸出 Lottie JSON 格式。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1383','task-366','<p>「生日優惠自動化觸發機制」測試任務旨在確保「CRM會員經營」的功能品質，需設計涵蓋正常流程、邊界條件與例外情況的測試案例，在 QA 環境完成驗收後出具測試報告。</p>','<p>1. 閱讀「生日優惠自動化觸發機制」的規格書，整理測試範圍（高風險功能優先）</p><p>2. 撰寫測試計畫：環境/策略/工具/測試資料準備</p><p>3. 設計測試案例：Happy Path + Edge Cases + Negative Tests</p><p>4. 執行功能測試，在任務留言更新測試結果（Pass/Fail/Blocked）</p><p>5. 執行回歸測試，確認不影響既有功能穩定性</p><p>6. Bug 回報：附上重現步驟、環境資訊、截圖/錄影</p><p>7. 輸出測試報告，列出已知問題與 Release 建議（Go/No-Go）</p>','<p>P1/P2 嚴重 Bug 請立刻在 Slack #urgent-bugs 頻道通知，不要等測試報告才揭露。測試環境為 QA 環境，不要在 Staging/Prod 進行破壞性測試。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1384','task-367','<p>「推播通知 A/B Test 分流框架」是「CRM會員經營」的產品規劃工作，目標是釐清業務需求、定義功能邊界，並與工程師、設計師對齊方向，輸出作為開發依據的規格文件。</p>','<p>1. 整理「推播通知 A/B Test 分流框架」的業務背景與使用者情境（User Story）</p><p>2. 撰寫完整功能規格書：流程圖、邊界條件、例外處理規則</p><p>3. 與工程師確認技術可行性，完成工作量估算（Story Point）</p><p>4. 與設計師對齊互動流程，確認設計稿交付時程</p><p>5. 定義驗收標準（Acceptance Criteria），作為 QA 測試依據</p><p>6. 主持需求評審，收集各方意見並更新文件版本</p><p>7. 規格確認後同步更新至 Notion，並在任務留言貼上連結</p>','<p>規格文件如有需求變更，需走正式 Change Request 流程並通知相關人員。評審後的最終版本需加版本號（v1.0）以防混淆。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1385','task-368','<p>「大量會員資料批次匯出優化」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1386','task-369','<p>「會員流失預測 ML 模型部署」是「CRM會員經營」的基礎設施/DevOps 任務，目標是提升系統可靠性、可觀測性或自動化程度，確保服務 SLA 達到 99.9% 可用性。</p>','<p>1. 評估「會員流失預測 ML 模型部署」的技術方案，比較主要選項的優缺點</p><p>2. 撰寫技術設計文件（TDD），確認涉及服務與影響範圍</p><p>3. 在非生產環境（Dev/QA）驗證方案可行性</p><p>4. 制定上線計畫：部署步驟、回滾策略、監控指標</p><p>5. 執行上線，密切監控 30 分鐘確認無異常</p><p>6. 更新 Runbook 與架構圖，確保團隊知識共享</p><p>7. 上線一週後進行穩定性回顧，確認指標達標</p>','<p>生產環境變更需提前 24 小時通知 SRE Lead 謝宗霖，並在 #deployments 頻道發佈變更公告。所有基礎設施變更需記錄 Change Log 供事後追溯。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1387','task-370','<p>「歷史訂單交叉購買關聯分析」涉及搜尋/數據/AI相關功能，需確保效能與準確性。</p>','<p>1. 確認搜尋索引與查詢優化策略</p><p>2. 實作並驗證搜尋結果品質</p><p>3. 效能壓測確保回應時間 < 200ms</p>','<p>搜尋相關功能需特別注意中文斷詞處理與索引更新策略。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1388','task-371','<p>「客服 SLA 達成率即時監控」是「CRM會員經營」的產品規劃工作，目標是釐清業務需求、定義功能邊界，並與工程師、設計師對齊方向，輸出作為開發依據的規格文件。</p>','<p>1. 整理「客服 SLA 達成率即時監控」的業務背景與使用者情境（User Story）</p><p>2. 撰寫完整功能規格書：流程圖、邊界條件、例外處理規則</p><p>3. 與工程師確認技術可行性，完成工作量估算（Story Point）</p><p>4. 與設計師對齊互動流程，確認設計稿交付時程</p><p>5. 定義驗收標準（Acceptance Criteria），作為 QA 測試依據</p><p>6. 主持需求評審，收集各方意見並更新文件版本</p><p>7. 規格確認後同步更新至 Notion，並在任務留言貼上連結</p>','<p>規格文件如有需求變更，需走正式 Change Request 流程並通知相關人員。評審後的最終版本需加版本號（v1.0）以防混淆。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1389','task-372','<p>「第三方 CRM 系統資料雙向同步」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1390','task-373','<p>「會員登入頻率與行為週期分析」涉及使用者認證與授權，是平台安全的核心組件，需確保安全性、效能與可擴展性。</p>','<p>1. 確認認證規格（JWT/OAuth 2.0/OIDC）與 Token 生命週期設計</p><p>2. 實作安全的 Token 生成/驗證/輪換機制</p><p>3. 實作細粒度角色/權限控制（RBAC）</p><p>4. 加入登入嘗試限制（Rate Limiting）防止暴力破解</p><p>5. 記錄認證稽核日誌（IP/時間/裝置/成功失敗）</p><p>6. 撰寫安全測試：XSS/CSRF/JWT 竄改攻擊向量</p><p>7. 更新認證相關 API 文件</p>','<p>Token 格式 Breaking Change 需提前一個 Sprint 通知前端並提供並行期。Token 有效期修改需確認對用戶體驗的影響。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1391','task-374','<p>「個性化商品推薦引擎整合」涉及搜尋/數據/AI相關功能，需確保效能與準確性。</p>','<p>1. 確認搜尋索引與查詢優化策略</p><p>2. 實作並驗證搜尋結果品質</p><p>3. 效能壓測確保回應時間 < 200ms</p>','<p>搜尋相關功能需特別注意中文斷詞處理與索引更新策略。</p>');
