INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1395','task-378','<p>「行銷活動 ROI 多維追蹤報表」涉及搜尋/數據/AI相關功能，需確保效能與準確性。</p>','<p>1. 確認搜尋索引與查詢優化策略</p><p>2. 實作並驗證搜尋結果品質</p><p>3. 效能壓測確保回應時間 < 200ms</p>','<p>搜尋相關功能需特別注意中文斷詞處理與索引更新策略。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1396','task-379','<p>「資料品質清洗與去重工具」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1397','task-380','<p>「黑名單與異常會員封鎖管理」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1398','task-381','<p>「GDPR 合規資料刪除申請流程」為後端核心功能，需確保穩定性、效能與安全性。</p>','<p>1. 確認 API 規格與資料庫設計</p><p>2. 實作核心業務邏輯與資料存取層</p><p>3. 撰寫單元測試與整合測試</p>','<p>後端功能需注意錯誤處理、日誌記錄與資料一致性。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1399','task-382','<p>「全產品線 Q2 OKR 規劃與優先級評審」是「棋牌遊戲」的產品規劃工作，目標是釐清業務需求、定義功能邊界，並與工程師、設計師對齊方向，輸出作為開發依據的規格文件。</p>','<p>1. 整理「全產品線 Q2 OKR 規劃與優先級評審」的業務背景與使用者情境（User Story）</p><p>2. 撰寫完整功能規格書：流程圖、邊界條件、例外處理規則</p><p>3. 與工程師確認技術可行性，完成工作量估算（Story Point）</p><p>4. 與設計師對齊互動流程，確認設計稿交付時程</p><p>5. 定義驗收標準（Acceptance Criteria），作為 QA 測試依據</p><p>6. 主持需求評審，收集各方意見並更新文件版本</p><p>7. 規格確認後同步更新至 Notion，並在任務留言貼上連結</p>','<p>規格文件如有需求變更，需走正式 Change Request 流程並通知相關人員。評審後的最終版本需加版本號（v1.0）以防混淆。</p>');
INSERT INTO task_specs ("id","task_id","background","requirement","notes") VALUES ('spec-1400','task-383','<p>「電商產品線營收目標追蹤與策略調整」是「商城主站」的產品規劃工作，目標是釐清業務需求、定義功能邊界，並與工程師、設計師對齊方向，輸出作為開發依據的規格文件。</p>','<p>1. 整理「電商產品線營收目標追蹤與策略調整」的業務背景與使用者情境（User Story）</p><p>2. 撰寫完整功能規格書：流程圖、邊界條件、例外處理規則</p><p>3. 與工程師確認技術可行性，完成工作量估算（Story Point）</p><p>4. 與設計師對齊互動流程，確認設計稿交付時程</p><p>5. 定義驗收標準（Acceptance Criteria），作為 QA 測試依據</p><p>6. 主持需求評審，收集各方意見並更新文件版本</p><p>7. 規格確認後同步更新至 Notion，並在任務留言貼上連結</p>','<p>規格文件如有需求變更，需走正式 Change Request 流程並通知相關人員。評審後的最終版本需加版本號（v1.0）以防混淆。</p>');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-001','m-001','早上 7:30–10:00 是我的深度思考時段，重大決策請約這個時間。每週三下午固定產品評審會，跨產線議題請帶到會上一次講清楚。','1. 急事直接打電話或當面找我，不用預約 2. 一般議題 Slack tag 我，24 小時內必回 3. 提案請先給一頁摘要：背景／選項／建議，不要只丟問題給我','卡在跨部門資源協調時直接來找我，這本來就是我的工作。技術債 vs 新功能的取捨拿不定，也歡迎拉我對齊，我判斷得很快。','1. 最忌諱問題捂到爆炸才說——壞消息請第一時間講 2. 會議遲到 3. 「大家都這樣做」不是理由，我要看數據','帶著方案來討論問題的人、主動寫覆盤文件的人，我都會記得。咖啡黑的不加糖，謝謝。','2026-07-08T02:15:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-002','m-002','週二週四整天排需求訪談與評審，其餘時間彈性。上午腦最清楚，複雜規格討論請約上午。','1. 需求相關一律開 LIVO 任務再 tag 我，別只在 Slack 講完就散 2. 跨產線衝突直接拉我，15 分鐘站著開完 3. Email 只用於對外窗口','規格寫到一半卡住時，我會先發 WIP 草稿收集意見。看到「WIP」標記請直接給建議，不用客氣。','1. 開發到一半才說需求不合理——評審時請當場提 2. 拿「使用者想要」當理由但拿不出訪談紀錄','需求評審前先看完文件再進會議室的人，我會記住你的好。','2026-07-06T09:30:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-003','m-003','沉浸在玩家數據裡的時候。每天早上先看前一天留存與付費數據，10 點後才切換成會議模式。','1. 遊戲產線需求一律走 LIVO，線上事故直接打電話 2. 我回訊息很快，但深夜訊息一律隔天早上回 3. 複雜脈絡我習慣用一段語音訊息講清楚','數值企劃卡關時我會找雅文一起跑模擬，歡迎旁聽；玩家輿情有異常我需要第一手截圖。','1. 未經討論直接改遊戲數值 2. 用「玩家會習慣」帶過體驗問題','主動回報玩家社群輿情的人是天使。','2026-07-09T03:40:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-004','m-004','大促前兩週是我的作戰模式，反應最快但也最忙。平常日下午最適合討論新需求。','1. 電商需求請附上預期的轉換率影響 2. Slack 頻道優先，私訊容易被洗掉 3. 每週五下午寫下週計畫，要插件請在那之前提出','卡在法務或金流合規時，我會直接約供應商開三方會議，需要拉誰進來請直說。','1. 上線日前一天才提「小調整」 2. 沒有 rollback 計畫的上線申請','幫我抓到活動文案錯字的人，飲料我請。','2026-07-07T08:20:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-005','m-005','戴上耳機進 Figma 就是心流時間，這時請用非同步訊息找我。下午 2–4 點開放 design review 預約。','1. 設計回饋請具體：哪個元件、什麼情境、期望行為 2. 「幫我美化一下」這種需求我會退回重寫 3. 設計稿意見直接標在 Figma 上，別用截圖轉述','需求模糊時我會先出低保真線稿確認方向——請在線稿階段就給意見，別等高保真才推翻。','1. 跳過設計直接開發、再回頭要我補設計稿 2. 用「不好看」三個字否定設計卻不給脈絡','開發前主動來對 spacing 與斷點細節的工程師，我愛你們。','2026-07-10T06:00:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-006','m-006','早上處理設計系統維護，下午做專案設計。趕稿期間會關通知，急件請找靜如協調。','1. 改稿請求請附截圖＋標注 2. 非急件我每天下午 5 點統一回覆 3. 動效規格用影片或 Lottie 檔溝通最快','插畫或視覺風格拿不定時，我會做 2–3 版丟到頻道投票，請大家踴躍出手。','1. 直接改我的設計稿檔案不留備份 2. 在群組說「隨便設計一下就好」','給我真實用戶截圖或操作錄影當設計輸入的人。','2026-07-05T07:45:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-007','m-007','上午 code review、下午寫程式。週五下午是前端技術分享會，歡迎丟題目給我排。','1. 技術問題先開 LIVO 任務、寫清楚重現步驟 2. PR 超過 400 行我會退回請拆小 3. 架構討論請約會議，不要在 Slack 打長文戰','卡效能問題時我會先開 Profiler 錄一段再分析，需要幫忙隨時找我 pair，不用不好意思。','1. 不寫測試就想合併 2. console.log 帶進 production 3. 繞過 design token 直接寫死顏色','主動重構老代碼還附上 before/after 數據的人。','2026-07-08T10:10:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-008','m-008','深夜是我的高產時段，但請別排我上午 11 點前的會。狀態管理、效能優化的難題儘管丟過來。','1. Slack 非同步優先，我看到就回 2. bug 回報請附 console 錯誤與重現步驟 3. 我打字比說話快，能文字就別開會','卡住超過 2 小時我會發文求救，附上已嘗試過的方向——也推薦大家用這個習慣，省大家時間。','1. 會議沒有 agenda 2. 被 cue「順便改一下」的範圍蔓延','PR description 寫得清楚的人，review 速度直接加倍。','2026-07-11T15:20:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-009','m-009','規律作息型，9–6 準時在線且效率穩定；超過 6 點請明天再說（線上事故除外）。','1. Vue 系列專案的元件問題直接找我 2. 我習慣在 LIVO 任務留言追蹤討論脈絡，重要結論請留在任務裡 3. 兩人面對面 10 分鐘勝過拉一群人開會','遇到瀏覽器相容性問題別自己撞牆，我有一份自建 checklist，找我拿。','1. 在 Vue 專案硬塞 React 思維的寫法 2. 改共用元件不通知使用方','發現我的元件文件過期並告訴我的人。','2026-07-04T05:30:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-010','m-010','專注在手機端體驗細節的時候。下午是真機測試時段，桌上排滿測試機，請勿約會議。','1. 手機端 bug 請註明機型／OS 版本／App 版本 2. 我常戴耳機測音效，傳訊息比在座位喊我有效 3. 週會後 30 分鐘是我的 open hour','iOS 審核被拒別慌，我處理過 20+ 次，附上被拒信截圖直接找我。','「在我電腦上是好的」——請先用真機驗過再提測。','願意用低階安卓機幫我抓效能問題的人是英雄。','2026-07-09T09:00:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-011','m-011','架構設計與 code review 是我的主場。早上 9–11 是固定 review 時段，PR 這時候丟最快被看到。','1. API 契約異動必須開任務並 tag 前端 2. 資料庫 schema 變更一律先找我過一輪 3. 事故處理期間我只看事故頻道，其他訊息晚點回','效能瓶頸抓不到時，我會先拉 slow query log 配 APM 對照，歡迎帶著監控截圖一起看。','1. 直接連 production DB 跑手寫 SQL 2. 沒有 migration 的 schema 變更 3. 在 code review 裡玩文字遊戲','事故後主動寫 post-mortem 的人；默默把 API 文件補齊的人。','2026-07-07T01:50:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-012','m-012','給我一副耳機和一杯手搖，交易系統的硬骨頭都啃得動。上午腦最清楚，難題請排上午。','1. 併發、事務、一致性問題是我的守備範圍，直接找我 2. 訊息請一次把事情講完整，不要只丟「在嗎」 3. 口頭結論請補文字紀錄，我只認文件','卡在分散式一致性問題時，我會先畫時序圖釐清邊界，要圖的跟我說一聲。','1. 在交易高峰期部署金流相關服務 2. catch 到例外之後默默吞掉','願意寫壓測腳本驗證我 API 的人，感謝你。','2026-07-10T02:30:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-013','m-013','快速原型與 API 開發是強項，「今天就要能動」的東西找我就對了。下午效率最高。','1. Slack 隨時敲，我回得很快 2. 需求給我使用情境就好，技術方案我來想 3. 站會請控制在 15 分鐘內，超時我會開始寫 code','Node 記憶體洩漏我有一套排查流程（heap snapshot 三連拍），卡住直接找我 pair。','1. 需求朝令夕改又不更新任務描述 2. 把「應該很簡單吧」掛在嘴邊','回報 bug 附上 request id 的人，直接進入效率天堂。','2026-07-11T04:10:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-014','m-014','跑模型的等待時間我會平行處理其他任務——看起來在滑手機，其實在等 GPU。深度工作集中在早上。','1. ML 需求請先講業務目標，不要直接指定演算法 2. 數據口徑問題先找雅文對齊，再來找我建模 3. 我的週報會附模型指標變化，想追蹤的訂閱任務即可','模型效果不如預期時，我需要 2–3 天的迭代空間；請別每小時問一次進度，結果不會因此變快。','1. 用單一個案否定整體模型效果 2. 直接改 feature pipeline 不打招呼','幫我標注資料的人都是恩人。','2026-07-06T06:40:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-015','m-015','系統平穩無事故的日子（拜託）。凌晨維護窗口隔天的早上，請讓我慢慢進入狀態。','1. 事故通報走事故頻道＋打電話雙保險 2. 部署申請請提前一天開任務 3. 「系統好像有點慢」請附時間點與 trace id，形容詞我無法 debug','容量規劃拿不準時我會先壓測再擴容——給我數據，別給我形容詞。','1. 週五下午部署 2. 繞過 CI/CD 手動改線上設定 3. 事故處理中在群組問「修好了嗎」','主動把服務接進監控告警的人；願意寫 runbook 的人。','2026-07-08T00:20:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-016','m-016','自動化一切可自動化的事。給我一天不被打斷的時間，我還你一條全自動 pipeline。','1. CI/CD 問題請附上 job 連結 2. 權限申請走表單，別私訊我 3. 我在處理部署時回覆會慢，非急件請稍等','遇到玄學 build 失敗，我的排查順序是：清 cache → 鎖依賴版本 → 找我。前兩步請先自己試。','1. pipeline 還沒綠燈就喊「可以上了」 2. 把密鑰寫進代碼','主動修 flaky test 的人是聖人，我說的。','2026-07-05T03:00:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-017','m-017','提測單寫得完整的日子，我的效率是三倍。回歸測試期間（雙週四五）請勿插件。','1. 提測請附測試範圍與影響面 2. bug 判定有爭議直接約 15 分鐘三方複現 3. 我的 bug 單分級很嚴格——P0 代表我已經站在你桌邊了','測試環境資料髒掉我會直接重建，有需要保留的資料請提前說。','1. 「先上線再補測」 2. 改了代碼不更新提測單範圍 3. 我回歸到一半時 force push','開發自己先跑過 smoke test 再提測的人，我幫你排優先。','2026-07-09T07:10:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-018','m-018','寫自動化腳本的時候。手動回歸我也做，但給我時間，我會把它變成自動化。','1. 我維護 E2E 測試套件，前端 selector 改動請通知我 2. 問題重現影片比文字描述快十倍 3. 每天下午 4 點後跑全量回歸，請勿部署測試環境','自動化工具選型卡住時，我會先各寫一個 POC 用數據比較，歡迎給我真實案例當測試場景。','1. 把測試環境當自己的沙盒亂改設定 2. 質疑自動化「不如手點快」','在元件上寫好 test id 讓我定位元素的前端，天使。','2026-07-10T08:50:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-019','m-019','早上跑數、下午解讀。給我明確的問題定義，我還你能落地的洞察。','1. 取數需求請說明用途與決策場景，不要只說「拉個數」 2. 口徑問題請先查數據字典再來問 3. 圖表需求請註明受眾：給老闆看和給工程師看是兩種做法','數據對不上時我的順序是先查埋點、再查 ETL，過程我會主動同步進度，不用一直問。','1. 拿片段數據斷章取義下結論 2. 週五下班前丟「老闆明天要」的需求','會自己用我做的 dashboard、而不是每次都要客製報表的人。','2026-07-07T05:15:00.000Z');
INSERT INTO member_manuals ("id","member_id","best_state","communication","difficulty","landmine","bonus","updated_at") VALUES ('mm-020','m-020','半夜批次任務全部綠燈的早晨。每天凌晨 2–4 點是 pipeline 維護窗口，那之後找我都在。','1. 數據管線需求請開任務寫清楚：來源／頻率／格式 2. schema 變更請提前三天告知，下游依賴很多 3. 我話少但文件寫很全，先看 wiki 再來問','上游數據亂掉時，我會先隔離髒數據再修管線。別催，催了也是這個順序。','1. 直接動 raw layer 的表 2. 「順便幫我同步一下」——同步從來沒有順便的','發現數據異常第一時間告訴我、而不是自己動手修的人。','2026-07-11T01:25:00.000Z');
