INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-050','task-238','m-014','<p>新版規則引擎在影子模式跑了 48 小時：命中率 97.2%、誤判率 0.4%，比舊版低一個數量級，完整報告在任務附註。</p>','2026-07-09T01:00:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-051','task-238','m-011','<p>數據很漂亮。切正式前先灰度 10% 房間跑三天，確認申訴率沒異常再全量。</p>','2026-07-10T03:00:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-052','task-238','m-017','<p>QA 這邊補一組對抗測試案例（模擬變速、封包重放），下週一給結果。</p>','2026-07-10T09:00:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-053','task-278','m-008','<p>卡頓原因找到了：角色移動時每幀都在重算陰影貼圖，改成快取後 FPS 從 41 回到 59。</p>','2026-07-10T02:50:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-054','task-278','m-007','<p>好修法。順手把這段寫進效能規範吧，其他場景八成也有同樣的問題。</p>','2026-07-10T04:10:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-055','task-278','m-018','<p>三台測試機驗證通過，低階機 FPS 也從 24 提升到 38，體感明顯，驗收 OK。</p>','2026-07-11T01:30:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-056','task-382','m-002','<p><span class="mention" data-id="m-001">@王建宏</span> Q2 OKR 草案我彙整好了：三條產品線共 9 個 Objective，其中金流合規和商城改版有資源衝突，需要你拍板優先序。</p>','2026-07-11T03:20:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-057','task-382','m-001','<p>金流合規優先，這是發證死線不能動。商城改版拆兩期，第一期只做結帳鏈路。下週一評審會過最終版。</p>','2026-07-11T05:00:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-058','task-382','m-003','<p>遊戲線補充：錦標賽功能若要趕暑期檔，美術資源要提前兩週鎖定，我把需求掛到對應任務了。</p>','2026-07-11T06:30:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-059','task-382','m-004','<p>電商線收到。結帳鏈路一期的範圍我今天重寫，明早給雅琪 review。</p>','2026-07-11T07:45:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-060','task-383','m-004','<p>6 月電商營收達成率 92%：商城 GMV +18%，但金流手續費侵蝕比預期高。詳細拆解表放在任務附註，建議把費率談判排進 Q3。</p>','2026-07-11T09:30:00.000Z',NULL,NULL,0);
INSERT INTO comments ("id","task_id","user_id","content","created_at","attachment_url","attachment_name","attachment_size") VALUES ('c-demo-061','task-383','m-001','<p>看完了。費率談判我來牽線，下週先約兩家收單行聊。轉換率那頁的漏斗圖做得很清楚，週一會議直接用。</p>','2026-07-12T01:15:00.000Z',NULL,NULL,0);
